svg.appendChild(el("text", {x:margin.left+8, y:refY-10, "text-anchor":"start", "font-size":"7", "font-weight":"700", fill:"#2e7d32", "font-family":FONT}, "VARIATION NULLE"));
svg.appendChild(el("text", {x:xp(12)-5, y:MT+12, "text-anchor":"end", "font-size":"7", "font-weight":"700", fill:"#1a3560", "font-family":FONT}, "MARS\u00a0: +0,9\u00a0%"));
svg.appendChild(el("text", {x:(xp(7)+xp(8))/2, y:MT+PH-8, "text-anchor":"middle", "font-size":"6.5", "font-weight":"700", fill:"#6b7280", "font-family":FONT}, "MANQUANT"));
